(4210437, 606330, 19982, '<td valign="top">I don''t care where this image lands in the end.  But it''s #1 in my book.  Just gave it a 10 and a favorite!  Great job!</td>', 'I don''t care where this image lands in the end.  But it''s #1 in my book.  Just gave it a 10 and a favorite!  Great job!', '2007-11-01 00:40:47.000000', NULL, 1),
(4210441, 601383, 49963, '<td valign="top">Beautiful shot!</td>', 'Beautiful shot!', '2007-11-01 00:41:47.000000', NULL, 1),
