(4210897, 604174, 34938, '<td valign="top">I like the light in this and the quirkinessof the shot</td>', 'I like the light in this and the quirkinessof the shot', '2007-11-01 03:07:42.000000', NULL, 1),
(4210898, 605785, 9668, '<td valign="top">Love it. Beautiful capture of this waterfall.</td>', 'Love it. Beautiful capture of this waterfall.', '2007-11-01 03:07:45.000000', NULL, 1),
