(4212021, 605555, 30982, '<td valign="top">The bokeh of the faces in the sun behind them really makes this a nice shot.</td>', 'The bokeh of the faces in the sun behind them really makes this a nice shot.', '2007-11-01 11:20:38.000000', NULL, 1),
(4212030, 607466, 30982, '<td valign="top">A fascinating picture to explore.  I love how the reflected window differs from the one visible and how the foreground reflections appear like piano keys.</td>', 'A fascinating picture to explore.  I love how the reflected window differs from the one visible and how the foreground reflections appear like piano keys.', '2007-11-01 11:22:03.000000', NULL, 1),
