(4215405, 605786, 65234, '<td valign="top">On first glance this seems overexposed, but looking longer the glow in the graveyard does look eerie.</td>', 'On first glance this seems overexposed, but looking longer the glow in the graveyard does look eerie.', '2007-11-02 10:08:24.000000', NULL, 1),
(4215407, 602025, 67152, '<td valign="top">pretty scene - the image seems a bit soft</td>', 'pretty scene - the image seems a bit soft', '2007-11-02 10:10:12.000000', NULL, 1),
(4215408, 604976, 84818, '<td valign="top">NICE CAPTURE!</td>', 'NICE CAPTURE!', '2007-11-02 10:10:26.000000', NULL, 1),
