(4215410, 601939, 67152, '<td valign="top">i simply love this</td>', 'i simply love this', '2007-11-02 10:12:17.000000', NULL, 1),
(4215412, 606400, 65234, '<td valign="top">Like the subject and selective desat.  Interesting framing effect; it''s clearly tilted, but balanced, while the little porch floor appears level.  I like this more the longer I look at it.</td>', 'Like the subject and selective desat.  Interesting framing effect; it''s clearly tilted, but balanced, while the little porch floor appears level.  I like this more the longer I look at it.', '2007-11-02 10:13:09.000000', NULL, 1),
(4215415, 605019, 84818, '<td valign="top">I LIKE THE COLORS BUT WOULD HAVE SATURATED A LITTLE LESS AND THERE IS SOME BLURRINESS.</td>', 'I LIKE THE COLORS BUT WOULD HAVE SATURATED A LITTLE LESS AND THERE IS SOME BLURRINESS.', '2007-11-02 10:13:34.000000', NULL, 1),
(4215416, 605287, 65234, '<td valign="top">Took me a minute to actually see what the performer was doing.  The bright sky is rather visually overpowering to me.</td>', 'Took me a minute to actually see what the performer was doing.  The bright sky is rather visually overpowering to me.', '2007-11-02 10:13:57.000000', NULL, 1),
