(4215432, 607174, 84818, '<td valign="top">BEAUTIFUL SHOT...I USE TO LIVE NEAR YOSIMITE AND THIS PHOTO TOOK ME BACK THERE.</td>', 'BEAUTIFUL SHOT...I USE TO LIVE NEAR YOSIMITE AND THIS PHOTO TOOK ME BACK THERE.', '2007-11-02 10:18:17.000000', NULL, 1),
(4215437, 607431, 65234, '<td valign="top">Paris seems to be somehwat askew.  Brightly lit, though.</td>', 'Paris seems to be somehwat askew.  Brightly lit, though.', '2007-11-02 10:20:37.000000', NULL, 1),
