(4229998, 606347, 83313, '<td valign="top">I need to stay away from voting on these free studies. My faves list is filling up too fast. This is great!</td>', 'I need to stay away from voting on these free studies. My faves list is filling up too fast. This is great!', '2007-11-07 20:38:51.000000', NULL, 1),
(4229999, 605609, 83313, '<td valign="top">He almost looks like a mannequin.good strong details showing on the wall.</td>', 'He almost looks like a mannequin.good strong details showing on the wall.', '2007-11-07 20:39:43.000000', NULL, 1),
(4230002, 607036, 83313, '<td valign="top">Nice, contrast.</td>', 'Nice, contrast.', '2007-11-07 20:40:29.000000', NULL, 1),
