(4230006, 607432, 83313, '<td valign="top">Good catch. Smooth sky in this.</td>', 'Good catch. Smooth sky in this.', '2007-11-07 20:42:18.000000', NULL, 1),
(4230007, 605017, 83313, '<td valign="top">Looks like something a kid would want to go exploring.</td>', 'Looks like something a kid would want to go exploring.', '2007-11-07 20:42:57.000000', NULL, 1),
